@startuml

class RepairShop {
  + name : string
  + address : string
  + numberOfEmployees : int
}

class Employee {
  + taxCode : string
  + address : string
  + phoneNumber : string
  + yearsOfService : int
}

class Director extends Employee {
  + age : int
}

class Repair {
  + code : string
  + checkInTime : datetime
  + checkInDate : date
  + returnTime : time
  + returnDate : date
}

class Vehicle {
  + model : string
  + type : string
  + licensePlate : string
  + registrationYear : int
}

class Owner {
  + taxCode : string
  + address : string
  + phoneNumber : string
}

RepairShop "1" -- "*" Employee
RepairShop "1" -- "1" Director
RepairShop "1" -- "*" Repair
Repair "*" -- "1" Vehicle
Vehicle "*" -- "1" Owner
Owner "1" -- "*" Vehicle
Repair "*" -- "1" Vehicle

@enduml

